import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  LineChart, Line, XAxis, YAxis, Tooltip,
  ResponsiveContainer, CartesianGrid, Legend,
} from 'recharts';
import { getRuns, getSummary } from '../services';

export default function Dashboard() {
  const [summary, setSummary] = useState(null);
  const [runs, setRuns] = useState([]);

  useEffect(() => {
    getSummary().then(setSummary).catch(console.error);
    getRuns().then(setRuns).catch(console.error);
  }, []);

  // ─────────────────────────────
  // SAFE TODAY OBJECT (NULL SAFE)
  // ─────────────────────────────
  const today = summary?.today || {
    total_tests: 0,
    passed: 0,
    failed: 0,
    skipped: 0
  };

  // ─────────────────────────────
  // SAFE TOTAL + PASS RATE (FIXED LOGIC)
  // ─────────────────────────────
  const total =
    (today.passed || 0) +
    (today.failed || 0) +
    (today.skipped || 0);

  const passRate = total
    ? Math.round((today.passed / total) * 100)
    : 0;

  const trend = summary?.trend || [];

  return (
    <div className="page">
      <h1 className="page-title">Dashboard</h1>

      {/* Stats cards */}
      <div className="stats-grid">

        <div className="stat-card">
          <div className="stat-value">{today.total_tests}</div>
          <div className="stat-label">Today's Tests</div>
        </div>

        <div className="stat-card green">
          <div className="stat-value">{today.passed}</div>
          <div className="stat-label">Passed</div>
        </div>

        <div className="stat-card red">
          <div className="stat-value">{today.failed}</div>
          <div className="stat-label">Failed</div>
        </div>

        <div className="stat-card blue">
          <div className="stat-value">{passRate}%</div>
          <div className="stat-label">Pass Rate</div>
        </div>

      </div>

      {/* Chart */}
      <div className="card">
        <h2>Pass Rate Trend - Last 14 Days</h2>

        <ResponsiveContainer width="100%" height={220}>
          <LineChart data={trend}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="run_date" />
            <YAxis domain={[0, 100]} unit="%" />
            <Tooltip formatter={(v) => `${Math.round(v)}%`} />
            <Legend />

            <Line
              type="monotone"
              dataKey="pass_rate"
              name="Pass Rate"
              stroke="#4f46e5"
              strokeWidth={2}
            />

            <Line
              type="monotone"
              dataKey="failed"
              name="Failures"
              stroke="#ef4444"
              strokeWidth={2}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Recent Runs */}
      <div className="card">
        <h2>Recent Runs</h2>

        <table className="table">
          <thead>
            <tr>
              <th>Run ID</th>
              <th>Started At</th>
              <th>Status</th>
              <th>Passed</th>
              <th>Failed</th>
              <th>Duration</th>
            </tr>
          </thead>

          <tbody>
            {runs.map((run) => (
              <tr key={run.id}>

                <td>
                  <Link to={`/runs/${run.id}`} className="link">
                    {run.id.slice(0, 8)}…
                  </Link>
                </td>

                <td>
                  {run.started_at
                    ? new Date(run.started_at).toLocaleString()
                    : '—'}
                </td>

                <td>
                  <span className={`badge ${run.status}`}>
                    {run.status}
                  </span>
                </td>

                <td className="green-text">{run.passed ?? 0}</td>
                <td className="red-text">{run.failed ?? 0}</td>

                <td>
                  {run.duration_ms
                    ? `${(run.duration_ms / 1000).toFixed(1)}s`
                    : '—'}
                </td>

              </tr>
            ))}

            {runs.length === 0 && (
              <tr>
                <td colSpan={6} style={{ textAlign: 'center' }}>
                  No runs found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

    </div>
  );
}
